from __future__ import annotations


def act_show_commands(arg, cfg, dry=False):
    """「命令列表」：打开唯一意图清单文件。"""
    try:
        from . import intents as _intents
        p = _intents.registry_file(cfg)
    except Exception as e:
        return False, f"定位意图清单失败: {type(e).__name__}: {e}", None
    if not p.exists():
        return False, f"意图清单不存在: {p}", None
    if dry:
        return True, f"[dry] 打开意图清单 → {p}", {"path": str(p)}
    try:
        import os as _os
        _os.startfile(str(p))          # Windows：默认程序（编辑器/记事本）打开
        return True, f"已打开意图清单（意图/说法/作用/是否开启）：{p}", {"path": str(p)}
    except Exception as e:
        return False, f"意图清单在 {p}，但打开失败: {type(e).__name__}: {e}", {"path": str(p)}
